/* ------------------------------------------------------------------ */
/* CATÁLOGO DINÁMICO: se arma desde Supabase (tablas 'categorias' y     */
/* 'productos'), NO desde datos hardcodeados. Estos helpers producen    */
/* exactamente la misma forma que antes tenía el catálogo estático     */
/* (SECTIONS / PRODUCTS_BY_ID), para no tocar el resto del componente.  */
/* ------------------------------------------------------------------ */

function slugify(text) {
  return (text || "")
    .toString()
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/(^-|-$)/g, "");
}

/* "01 OLD TIME GREEN" -> { numero: "01", title: "Old Time Green" }.
   Si no hay número al inicio, o si subgrupo es null (ej. "BEBIDAS",
   que es una lista plana), no hay encabezado (numero/title = null),
   igual que las categorías sin "groups.title" en el catálogo viejo. */
function parseSubgrupo(subgrupo) {
  if (!subgrupo) return { numero: null, title: null };
  const match = subgrupo.match(/^(\d+)\s+(.*)$/);
  if (match) return { numero: match[1], title: match[2] };
  return { numero: null, title: subgrupo };
}

/* Arma [{ key, label, groups: [{ numero, title, items: [...] }] }] a
   partir de las filas planas de 'categorias' + 'productos'. Es la
   MISMA forma que antes producía el array SECTIONS hardcodeado. */
function buildSectionsFromRows(categoriaRows, productoRows) {
  return categoriaRows.map((cat) => {
    const productosDeCategoria = productoRows
      .filter((p) => p.categoria === cat.nombre)
      .sort((a, b) => a.orden - b.orden);

    // Agrupa por 'subgrupo' preservando el orden de aparición.
    const groupsOrder = [];
    const groupsMap = new Map();
    productosDeCategoria.forEach((p) => {
      const groupKey = p.subgrupo || "__sin_subgrupo__";
      if (!groupsMap.has(groupKey)) {
        groupsMap.set(groupKey, []);
        groupsOrder.push(groupKey);
      }
      groupsMap.get(groupKey).push(p);
    });

    const groups = groupsOrder.map((groupKey) => {
      const { numero, title } = parseSubgrupo(
        groupKey === "__sin_subgrupo__" ? null : groupKey
      );
      return {
        numero,
        title,
        items: groupsMap.get(groupKey).map((p) => ({
          id: p.id,
          combo: p.etiqueta || undefined,
          name: p.nombre,
          detail: p.descripcion || "",
          price: Number(p.precio),
          consumes: Array.isArray(p.consumos) ? p.consumos : JSON.parse(p.consumos || "[]"),
        })),
      };
    });

    return { key: slugify(cat.nombre), label: cat.nombre, groups };
  });
}

function buildProductsById(sections) {
  const map = {};
  sections.forEach((section) => {
    section.groups.forEach((group) => {
      group.items.forEach((item) => {
        map[item.id] = { ...item, sectionLabel: section.label };
      });
    });
  });
  return map;
}

const EDIT_PASSWORD = "edit";

/* Costo asumido por producto para calcular la Ganancia Neta.
   No existe todavía una columna de costos reales en la tabla
   'productos' de Supabase, así que se asume un costo = 55% del
   precio de venta. Ajusta este número (o agrega una columna "costo"
   a 'productos' y úsala aquí) cuando tengas tus costos reales. */
const DEFAULT_COST_RATIO = 0.55;

function unitCostFor(product) {
  if (!product) return 0;
  return product.cost != null ? product.cost : product.price * DEFAULT_COST_RATIO;
}

const PAYMENT_METHODS = [
  { key: "YAPE", label: "Yape" },
  { key: "PLIN", label: "Plin" },
  { key: "OTROS", label: "Otros" },
];

/* Intenta detectar, a partir del texto que devuelve el OCR, el método
   de pago (Yape / Plin / Otro), el ID / código de operación y el
   monto pagado. */
function detectPaymentInfo(rawText) {
  const text = (rawText || "").toUpperCase();

  let method = "OTROS";
  if (text.includes("YAPE")) method = "YAPE";
  else if (text.includes("PLIN")) method = "PLIN";

  const idPatterns = [
    /N[°ºO.]{0,3}\s*(?:DE\s*)?OPERACI[OÓ]N[:\s]*([A-Z0-9-]{4,20})/,
    /C[OÓ]DIGO\s*(?:DE\s*)?OPERACI[OÓ]N[:\s]*([A-Z0-9-]{4,20})/,
    /N[°ºO.]{0,3}\s*OPERACI[OÓ]N[:\s]*([A-Z0-9-]{4,20})/,
    /ID[:\s]*([A-Z0-9-]{4,20})/,
  ];

  let opId = null;
  for (const re of idPatterns) {
    const m = text.match(re);
    if (m && m[1]) {
      opId = m[1];
      break;
    }
  }
  if (!opId) {
    // Como último recurso, busca la secuencia numérica más larga del texto.
    const numbers = text.match(/\d{6,}/g);
    if (numbers && numbers.length > 0) {
      opId = numbers.sort((a, b) => b.length - a.length)[0];
    }
  }

  // Monto: primero busca una etiqueta explícita ("Monto", "Pago",
  // "Total", "Importe"); si no aparece, cae al primer número junto al
  // símbolo de Soles "S/". El usuario siempre revisa esta cifra antes
  // de guardar, así que un acierto aproximado ya es útil.
  const amountPatterns = [
    /(?:MONTO|PAGO|TOTAL|IMPORTE)[:\s]*S?\s?\/?\.?\s*(\d{1,6}(?:[.,]\d{1,2})?)/,
    /S\s?\/\.?\s*(\d{1,6}(?:[.,]\d{1,2})?)/,
  ];

  let amount = null;
  for (const re of amountPatterns) {
    const m = text.match(re);
    if (m && m[1]) {
      amount = m[1].replace(",", ".");
      break;
    }
  }

  return { method, opId, amount };
}

/* ------------------------------------------------------------------ */
/* HELPERS                                                             */
/* ------------------------------------------------------------------ */

function formatSoles(n) {
  return `S/ ${Number(n).toFixed(n % 1 === 0 ? 0 : 2)}`;
}

/* Arma el texto del resumen de compra para el CRM básico de WhatsApp. */
function buildSaleWhatsappMessage(sale) {
  const lines = sale.items.map(
    (it) =>
      `• ${it.name}${it.detail ? ` (${it.detail})` : ""} x${it.qty} — ${formatSoles(it.total)}`
  );
  const greeting = sale.nombre ? `Hola ${sale.nombre}, ` : "Hola, ";
  return `${greeting}aquí tienes el resumen de tu compra en Tonazo:\n\n${lines.join(
    "\n"
  )}\n\nTotal: ${formatSoles(sale.total)}\n¡Gracias por tu compra!`;
}

function formatDate(ts) {
  const d = new Date(ts);
  return d.toLocaleDateString("es-PE", {
    day: "2-digit",
    month: "2-digit",
    year: "numeric",
  });
}

function formatTime(ts) {
  const d = new Date(ts);
  return d.toLocaleTimeString("es-PE", {
    hour: "2-digit",
    minute: "2-digit",
  });
}

/* Medianoche (hora local) del día que contiene el timestamp dado.
   Se usa como respaldo del corte de turno cuando todavía no se ha
   hecho ningún Cierre de Caja. */
function startOfDay(ts) {
  const d = new Date(ts);
  d.setHours(0, 0, 0, 0);
  return d.getTime();
}

function availabilityFor(product, stock) {
  if (!product.consumes || product.consumes.length === 0) return Infinity;
  return Math.min(
    ...product.consumes.map((c) => Math.floor((stock[c.key] ?? 0) / c.qty))
  );
}

function nextPurchaseId(sales) {
  let max = 0;
  sales.forEach((s) => {
    const m = /^V-(\d+)$/.exec(s.purchaseId || "");
    if (m) max = Math.max(max, parseInt(m[1], 10));
  });
  return `V-${String(max + 1).padStart(4, "0")}`;
}

